using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>A real HTTP server on loopback standing in for the provider's REST API.</summary>
internal sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly int statusCode;
    private readonly string responseBody;

    public FakeProvider(int statusCode, string responseBody)
    {
        this.statusCode = statusCode;
        this.responseBody = responseBody;

        var port = GetFreePort();
        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"http://127.0.0.1:{port}/");
        listener.Start();
        _ = Task.Run(ServeAsync);
    }

    public Uri BaseAddress { get; }
    public string? Method { get; private set; }
    public string? Path { get; private set; }
    public string? ContentType { get; private set; }
    public string? Body { get; private set; }

    private async Task ServeAsync()
    {
        try
        {
            var context = await listener.GetContextAsync();
            var request = context.Request;
            using (var reader = new StreamReader(request.InputStream, Encoding.UTF8))
            {
                Body = await reader.ReadToEndAsync();
            }
            Method = request.HttpMethod;
            Path = request.Url?.AbsolutePath;
            ContentType = request.ContentType;

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            context.Response.StatusCode = statusCode;
            context.Response.ContentType = "application/json";
            context.Response.ContentLength64 = bytes.Length;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
        catch (Exception) when (!listener.IsListening)
        {
        }
    }

    private static int GetFreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose() => listener.Close();
}
